mapper.select:
SELECT t.tag_id, t.tag_name, t.color_code, t.is_active, t.display_order, t.created_at, t.updated_at, CASE WHEN mt.tag_id IS NULL THEN 0 ELSE 1 END AS assigned FROM tl_tags t LEFT JOIN tl_meetings_tag mt ON mt.tag_id = t.tag_id AND mt.meeting_id = #{meetingId}
WHERE t.is_active = 1
ORDER BY COALESCE(t.display_order, 999999), t.tag_id

mapper.delete:
DELETE FROM tl_meetings_tag
WHERE meeting_id = #{meetingId}
  AND tag_id     = #{tagId}

DELETE FROM tl_meetings_tag
WHERE meeting_id = #{meetingId}

  AND tag_id NOT IN

    #{id}
